// The client-half bundler: emits a harness-shaped client bundle.
//
// THE CONTRACT (verified against the harness source):
// `packages/preset/agent-preset/skills/cordis-plugin-development/templates/
// decoration/client.js` and `packages/client/tsdown.client.ts`: a client
// bundle is a CLASSIC script (no ESM imports) that calls
// `window.__ModuleLoader__.load({ id, factory(require) })`; the factory
// returns the client plugin module ({ inject, apply, default }), and the
// injected `require` resolves the module-table externals (react, ...).
//
// This script bundles the package's client entry to CJS with esbuild (the
// package's tsconfig paths resolve the @Function/@Interface/@Variable
// aliases; the locale JSON is inlined), then wraps the output in the
// closure-factory envelope above and writes Target/Client.bundle.js.
// The ESM Target/Client.js stays the dev/test surface; the package's
// `exports["./client"]` points the module system at the bundle.
//
// Usage (from the package directory):
//   node ../../../Maintain/Build-Client-Bundle.mjs . <entry> <packageName>
import * as FS from "node:fs";
import * as Path from "node:path";

import { build } from "esbuild";

const [PackageDirectory, Entry, PackageName] = process.argv.slice(2);

switch (true) {
	case typeof PackageDirectory !== "string" || PackageDirectory.length === 0:
	case typeof Entry !== "string" || Entry.length === 0:
	case typeof PackageName !== "string" || PackageName.length === 0:
		console.error(
			"usage: node Maintain/Build-Client-Bundle.mjs <packageDir> <entry> <packageName>",
		);
		process.exit(1);
}

const Root = Path.resolve(PackageDirectory);
const Result = await build({
	bundle: true,
	entryPoints: [Path.join(Root, Entry)],
	external: ["react", "react-dom", "react/jsx-runtime"],
	format: "cjs",
	logLevel: "silent",
	platform: "browser",
	target: "es2022",
	tsconfig: Path.join(Root, "tsconfig.json"),
	write: false,
});

const Code = Result.outputFiles[0].text;
const Output = [
	`// The client half of ${PackageName} - generated by`,
	"// Maintain/Build-Client-Bundle.mjs (the harness client-bundle contract:",
	"// window.__ModuleLoader__.load({ id, factory(require) })).",
	"// Never hand-edit; rebuild with the package's prepublishOnly.",
	"window.__ModuleLoader__.load({",
	`\tid: ${JSON.stringify(PackageName)},`,
	"\tfactory(require) {",
	"\t\tconst module = { exports: {} };",
	"\t\t(function (module, exports, require) {",
	Code,
	"\t\t})(module, module.exports, require);",
	"\t\treturn module.exports;",
	"\t},",
	"});",
	"",
].join("\n");

FS.mkdirSync(Path.join(Root, "Target"), { recursive: true });
FS.writeFileSync(Path.join(Root, "Target/Client.bundle.js"), Output);
console.log("client bundle written:", Path.join(Root, "Target/Client.bundle.js"));
